    def on_button_click(self, row, col):
        if not self.game.game_over and self.game.place_stone(row, col):
            self.update_board()
    def update_board(self):
        for row in range(15):
            for col in range(15):
                if self.game.board[row][col] is not None:
                    self.buttons[row][col].config(text=str(self.game.board[row][col]))
